import{z as o,x as A,o as t,c as d,q as l,j as i,D as e,d as r,s as B,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"树作为无环连通图","description":"","frontmatter":{"title":"树作为无环连通图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tree-as-acyclic.md","filePath":"cs/tree-as-acyclic.md","lastUpdated":1791413859000}'),p={name:"cs/tree-as-acyclic.md"};function c(D,a,m,C,h,u){const s=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="树作为无环连通图" tabindex="-1">树作为无环连通图 <a class="header-anchor" href="#树作为无环连通图" aria-label="Permalink to &quot;树作为无环连通图&quot;">​</a></h1><div class="epigraph"><p>连通且无回路的有限无向图，边数必是顶点数减一；任意两点恰有一条路。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/degree-cut">度、连通与割</a>钉死了 \\(G=(V,E)\\) 与路、连通。本课不重讲度数和，也不从「文件系统目录」另起。缺口是：一般图可以有回路。归纳、后课递归数据结构、生成树，需要一种<strong>没有回路还连通</strong>的图，使「去掉叶再归纳」合法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连通图可以有多余的边围成圈；有圈则「父指针」会打环，结构归纳没有更小的子对象。缺口因此不是新的边类型，而是刻画树：有限无向简单图 \\(T\\) 是树，当它连通且无回路。等价条件（任证一条，其余作定理）：\\(|E|=|V|-1\\) 且连通；任意两点恰一条路；连通但删任一边不连通。</p><p><span class="marginnote">术语翻译：「连通且无回路」还能换成三种说法——边数恰是点数减一、任意两点恰有一条路、删任何一条边都会断开。四句话刻画同一类图，证明时任选一条推其余。</span></p><p>有根树是另加一个根、把边看成指向子节点；那是表示，不是无向树定义的一部分。本课两者都用，后课递归算法默认有根。</p><h3 id="树不是「长得像树枝的图」" tabindex="-1">树不是「长得像树枝的图」 <a class="header-anchor" href="#树不是「长得像树枝的图」" aria-label="Permalink to &quot;树不是「长得像树枝的图」&quot;">​</a></h3><p>有根二叉树在数据结构课才加「左孩子右孩子」。本课的树可以任意度数。把二叉树当成本课定义，后课并查集、最小生成树的「树」会对不上。森林是无环图，分量都是树。</p><p><span class="marginnote">Rosen 列出树的等价定义并要求会互推。\\(|E|=|V|-1\\) 用归纳：叶存在（除非单点），删叶后仍是树。本课不把生成树算法写出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先证：非平凡有限树至少两片叶（度数 1）。删叶，\\(|V|\\)、\\(|E|\\) 同减一，归纳得 \\(|E|=|V|-1\\)。反之，连通且 \\(|E|=|V|-1\\) 则无环，否则删圈上边仍连通，边更少，与极小连通矛盾。</p><p><span class="marginnote">数字实例：8 个顶点的树必有 7 条边；再加 1 条边必有圈，再删 1 条边必断开。这个「差一」的刚性就是 \\(|E|=|V|-1\\) 的全部含义。</span></p>',13)),(t(),i(n,null,{default:e(()=>[B(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%BF%9E%E9%80%9A%E6%97%A0%E5%90%91%E5%9B%BE%22%5D%20--%3E%20ACY%5B%22%E6%97%A0%E5%9B%9E%E8%B7%AF%22%5D%0A%20%20ACY%20--%3E%20TREE%5B%22%E6%A0%91%EF%BC%9A%7CE%7C%20%3D%20%7CV%7C-1%22%5D%0A%20%20TREE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AE%A1%E6%95%B0%E4%B8%8E%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"树上归纳合法：对 \\(|V|\\) 归纳，或沿根向叶子。后课文件系统、堆、BST 都是有根有序树，代价分析用高度；本课只保证无环故高度有定义（有根时）。图若有环，DFS 会遇到回边——算法课再分边类型；本课只提供「无环」这个前提。",-1)),a[5]||(a[5]=E("p",null,"生成树是原图的生成子图且为树，边数仍是 \\(|V|-1\\)。存在性当且仅当原图连通。算法（Kruskal、Prim）很后，本课只承认对象。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为树必须长得上下分层、有根有方向。本课定义里树就是无环连通图，横着画、乱画都行；「有根、有序、二叉」全是后课额外附加的标记。")],-1)),(t(),i(n,null,{default:e(()=>[B(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%B8%80%E6%A3%B5%E6%A0%91%EF%BC%9A%7CE%7C%20%3D%20%7CV%7C%20-%201%22%5D%20--%3E%20ADD%7B%22%E5%9C%A8%E4%BB%BB%E6%84%8F%E4%B8%A4%E7%82%B9%E9%97%B4%3Cbr%2F%3E%E5%8A%A0%E4%B8%80%E6%9D%A1%E8%BE%B9%EF%BC%9F%22%7D%0A%20%20ADD%20--%3E%20CYCLE%5B%22%E4%B8%A4%E7%82%B9%E6%9C%AC%E6%9C%89%E5%94%AF%E4%B8%80%E8%B7%AF%3Cbr%2F%3E%E6%96%B0%E8%BE%B9%E4%B8%8E%E4%B9%8B%E5%9B%B4%E6%88%90%E5%9C%88%3Cbr%2F%3E%E4%B8%8D%E5%86%8D%E6%98%AF%E6%A0%91%22%5D%0A%20%20T%20--%3E%20DEL%7B%22%E5%88%A0%E6%8E%89%E4%B8%80%E6%9D%A1%E8%BE%B9%EF%BC%9F%22%7D%0A%20%20DEL%20--%3E%20SPLIT%5B%22%E6%A0%91%E8%A2%AB%E5%88%87%E6%88%90%E4%B8%A4%E6%A3%B5%3Cbr%2F%3E%E4%B8%8D%E5%86%8D%E8%BF%9E%E9%80%9A%22%5D%0A%20%20T%20--%3E%20LEAF%7B%22%E6%91%98%E6%8E%89%E4%B8%80%E7%89%87%E5%8F%B6%EF%BC%9F%22%7D%0A%20%20LEAF%20--%3E%20OK%5B%22V%20%E4%B8%8E%20E%20%E5%90%8C%E5%87%8F%E4%B8%80%3Cbr%2F%3E%E5%89%A9%E4%B8%8B%E4%BB%8D%E6%98%AF%E6%A0%91%3Cbr%2F%3E%E5%BD%92%E7%BA%B3%E7%9A%84%E8%90%BD%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入有向无环图（DAG）的等价刻画——那是数据结构课末的叶子。也不把根树的平面画法、括号表示写成语法。有向树（每个点入度 1 除根）是另一套，后课再需要时再钉。</p><p>后课默认：谈到树，无向意义下连通无环；\\(|E|=|V|-1\\)。有根是额外结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>树 = 有限连通无环图；等价于恰 \\(|V|-1\\) 条边且连通。</li><li>两点之间唯一路；可删叶做归纳。</li><li>有根、有序、二叉都是后课加上的数据。</li><li>出处：Rosen, <em>Discrete Mathematics</em>。</li></ul>',5))])}const f=o(p,[["render",c]]);export{T as __pageData,f as default};
